<?php
function accounting_http_checks(mysqli $db,string $testName,array $payload):void {
    $socket=stream_socket_server('tcp://127.0.0.1:0',$errno,$errstr);if(!$socket)throw new RuntimeException('Test port unavailable');$address=stream_socket_get_name($socket,false);fclose($socket);$port=(int)substr($address,strrpos($address,':')+1);
    putenv('CREATIVA_RAB_TEST_DB='.$testName);$log=tempnam(sys_get_temp_dir(),'accounting-http-');
    $server=proc_open([PHP_BINARY,'-d','session.save_path='.sys_get_temp_dir(),'-d','upload_tmp_dir='.sys_get_temp_dir(),'-S','127.0.0.1:'.$port,__DIR__.'/budget_test_router.php'],[['pipe','r'],['file',$log,'a'],['file',$log,'a']],$pipes,dirname(__DIR__,2));if(!is_resource($server))throw new RuntimeException('Cannot start isolated HTTP tests');fclose($pipes[0]);
    try{
        for($i=0;$i<60;$i++){$ready=@stream_socket_client('tcp://127.0.0.1:'.$port,$errno,$errstr,.1);if($ready){fclose($ready);break;}usleep(100000);}
        $send=function(string $url,string $method='GET',?array $body=null,string $cookie='',string $csrf='',?string $proof=null)use($port):array{
            $headers=['Content-Type: application/json'];$content=$body===null?'':json_encode($body);
            if(isset($body['__form'])){$headers=['Content-Type: application/x-www-form-urlencoded'];$content=http_build_query($body['__form']);}
            if($proof!==null){$boundary='ac'.bin2hex(random_bytes(8));$headers=['Content-Type: multipart/form-data; boundary='.$boundary];$content="--$boundary\r\nContent-Disposition: form-data; name=\"payload\"\r\n\r\n".json_encode($body)."\r\n--$boundary\r\nContent-Disposition: form-data; name=\"proof\"; filename=\"proof.png\"\r\nContent-Type: image/png\r\n\r\n$proof\r\n--$boundary--\r\n";}
            if($cookie)$headers[]='Cookie: '.$cookie;if($csrf)$headers[]='X-CSRF-Token: '.$csrf;
            $context=stream_context_create(['http'=>['method'=>$method,'header'=>implode("\r\n",$headers),'content'=>$content,'ignore_errors'=>true,'timeout'=>15]]);$raw=file_get_contents('http://127.0.0.1:'.$port.'/'.$url,false,$context);$responseHeaders=$http_response_header??[];preg_match('/\s(\d{3})\s/',$responseHeaders[0]??'',$match);$session='';foreach($responseHeaders as $h)if(str_starts_with(strtolower($h),'set-cookie:'))$session=explode(';',trim(substr($h,11)))[0];return ['code'=>(int)($match[1]??0),'json'=>json_decode($raw,true),'cookie'=>$session,'body'=>$raw,'headers'=>$responseHeaders];
        };
        check($send('accounting.php')['code']===401,'HTTP ledger requires session');check($send('accounting.php?view=export')['code']===401,'HTTP export requires session');check($send('finance.php')['code']===401,'Legacy finance no anonymous access');
        $login=$send('login.php','POST',['email'=>'finance@test','password'=>'isolated-test-only']);check($login['json']['status']==='success'&&$login['cookie']!=='','HTTP login establishes verified actor');$cookie=$login['cookie'];
        $lookups=$send('accounting.php?view=lookups','GET',null,$cookie);check($lookups['code']===200&&$lookups['json']['permissions']['prepare']&&!$lookups['json']['permissions']['approve'],'HTTP master data and permission metadata');$csrf=$lookups['json']['csrf_token'];
        $input=$payload+['action'=>'create','created_by'=>2,'role'=>'admin'];$input['request_key']=bin2hex(random_bytes(16));
        check($send('accounting.php','POST',$input,$cookie)['code']===403,'HTTP CSRF required');$before=ac_one($db,'SELECT COUNT(*) AS n FROM accounting_transactions')['n'];
        $bad=$send('accounting.php','POST',$input,$cookie,$csrf,'<html>Not an image</html>');check($bad['code']===422&&$before===ac_one($db,'SELECT COUNT(*) AS n FROM accounting_transactions')['n'],'Invalid multipart proof rolls back draft');
        $png=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aN2kAAAAASUVORK5CYII=');$created=$send('accounting.php','POST',$input,$cookie,$csrf,$png);check($created['code']===200,'HTTP real proof upload');$id=(int)$created['json']['data']['id'];$detail=$send('accounting.php?view=detail&id=transaction:'.$id,'GET',null,$cookie);check((int)$detail['json']['data']['transaction']['created_by']===1,'HTTP actor spoof ignored');
        $retry=$send('accounting.php','POST',$input,$cookie,$csrf,$png);check((int)$retry['json']['data']['id']===$id&&ac_one($db,'SELECT COUNT(*) AS n FROM accounting_transactions')['n']==$before+1,'HTTP multipart retry no duplicate');
        check($send('accounting.php?view=proof&id='.$id)['code']===401,'Proof requires authenticated reader');$proof=$send('accounting.php?view=proof&id='.$id,'GET',null,$cookie);check($proof['code']===200&&$proof['body']===$png,'Authenticated proof matches uploaded bytes');
        $student=$send('login.php','POST',['email'=>'student@test','password'=>'isolated-test-only']);check($send('accounting.php','GET',null,$student['cookie'])['code']===403,'Student cannot read financial book');check($send('accounting.php?view=export','GET',null,$student['cookie'])['code']===403,'Student cannot export financial data');
        $rows=$send('accounting.php?view=export_data&classification=owner_capital','GET',null,$cookie);$csv=$send('accounting.php?view=export&classification=owner_capital','GET',null,$cookie);check($rows['code']===200&&count($rows['json']['data']['rows'])===3,'Filtered Excel data uses all matching server rows');check($csv['code']===200&&str_contains($csv['body'],'5000.25')&&!str_contains($csv['body'],'loan_receipt'),'Filtered CSV preserves numeric amounts');
        $stats=$send('sensei_dashboard_stats.php','GET',null,$send('login.php','POST',['email'=>'sensei@test','password'=>'isolated-test-only'])['cookie']);check($stats['code']===200&&$stats['json']['data']['total_siswa']===1,'Sensei roster count uses real master, no 48 fallback');check($send('sensei_dashboard_stats.php')['code']===401,'Sensei statistics require login');
        $studentCookie=$student['cookie'];$lms=$send('lms_dashboard_stats.php?siswa_id=5','GET',null,$studentCookie);check($lms['code']===200&&$lms['json']['data']['rata_rata_nilai']==50,'LMS average includes real zero grade');check($send('lms_dashboard_stats.php?siswa_id=3','GET',null,$studentCookie)['code']===403,'Student cannot spoof another statistics ID');check(count(array_filter($lms['json']['data']['aktivitas_terakhir'],fn($a)=>$a['type']==='materi'))===0,'No invented material-reading activity');
        $beforeStudents=ac_one($db,'SELECT COUNT(*) AS n FROM peserta_intensif')['n'];$gradeRows=$send('lms_grades.php','GET',null,$studentCookie);check($gradeRows['code']===200&&count($gradeRows['json']['data'])===1&&$beforeStudents===ac_one($db,'SELECT COUNT(*) AS n FROM peserta_intensif')['n'],'Grade reads scoped to student and never auto-create roster');$studentToken=$send('session.php','GET',null,$studentCookie)['json']['csrf_token'];check($send('lms_grades.php','POST',['siswa_id'=>1,'quiz'=>100,'latihan1'=>100,'latihan2'=>100,'kaiwa'=>100],$studentCookie,$studentToken)['code']===403,'Student cannot edit grades');
        foreach(['lms_meetings.php','lms_tasks.php','lms_submissions.php','lms_attendance.php'] as $endpoint)check($send($endpoint)['code']===401,'LMS endpoint requires login: '.$endpoint);
        $ownSubs=$send('lms_submissions.php','GET',null,$studentCookie);if(!is_array($ownSubs['json']))throw new RuntimeException('Isolated LMS response: '.substr($ownSubs['body'],0,800));check($ownSubs['code']===200&&count($ownSubs['json']['data'])===2,'Student submissions restricted to authenticated owner');check($send('lms_submissions.php?siswa_id=3','GET',null,$studentCookie)['code']===403,'Submission ID spoof rejected');
        check($send('lms_submissions.php','POST',['__form'=>['action'=>'grade','submission_id'=>1,'grade'=>100]],$studentCookie,$studentToken)['code']===403,'Learner cannot grade through submission API');
        $otherTeacher=$send('login.php','POST',['email'=>'other-sensei@test','password'=>'isolated-test-only'])['cookie'];$otherToken=$send('session.php','GET',null,$otherTeacher)['json']['csrf_token'];check($send('lms_submissions.php','POST',['__form'=>['action'=>'grade','submission_id'=>1,'grade'=>100]],$otherTeacher,$otherToken)['code']===403,'Sensei cannot grade another assignment');
        $otherSubs=$send('lms_submissions.php','GET',null,$otherTeacher);check($otherSubs['code']===200&&count($otherSubs['json']['data'])===0,'Sensei reads only assigned meeting submissions');
        $teacherCookie=$send('login.php','POST',['email'=>'sensei@test','password'=>'isolated-test-only'])['cookie'];$teacherToken=$send('session.php','GET',null,$teacherCookie)['json']['csrf_token'];$qr=$send('lms_attendance.php','POST',['meeting_id'=>1,'action'=>'issue_session'],$teacherCookie,$teacherToken);check($qr['code']===200,'Teacher issues expiring attendance token');
        check($send('lms_attendance.php','POST',['meeting_id'=>1,'siswa_id'=>3,'action'=>'check_in','token'=>$qr['json']['data']['token']],$studentCookie,$studentToken)['code']===200&&ac_one($db,'SELECT COUNT(*) AS n FROM lms_attendance WHERE siswa_id=3')['n']==0,'Attendance ignores spoofed student identity and returns actual name');
        check($send('lms_meetings.php','POST',['title'=>'Spoof class'],$studentCookie,$studentToken)['code']===403,'Student cannot create instructor agenda');
        check($send('lms_meetings.php?id=1','DELETE',null,$otherTeacher,$otherToken)['code']===403,'Sensei cannot delete another assigned meeting');
        $operational=$send('dashboard_stats.php','GET',null,$cookie);check($operational['code']===200&&$operational['json']['operational']['students']===1&&$operational['json']['operational']['active_sensei']===2,'Operational dashboard KPIs come from real tables');check($operational['json']['data']['matching']===0&&$operational['json']['availability']['matching'],'Empty existing operational table reports verified zero');check($send('dashboard_stats.php','GET',null,$studentCookie)['code']===403,'Operational roster requires configured financial read access');
        check($send('reimbursements.php?role=admin&user_id=2')['code']===401,'Reimbursement ignores unauthenticated role spoof');check($send('reimbursements.php','PUT',['id'=>1,'status'=>'approved'],$studentCookie,$studentToken)['code']===403,'Learner cannot approve reimbursement');$adminSession=$send('login.php','POST',['email'=>'admin@test','password'=>'isolated-test-only'])['cookie'];$adminToken=$send('session.php','GET',null,$adminSession)['json']['csrf_token'];check($send('reimbursements.php','PUT',['id'=>1,'status'=>'approved','finance_notes'=>'Struk diverifikasi'],$adminSession,$adminToken)['code']===200,'Reimbursement reviewer decision stored atomically');check($send('reimbursements.php','PUT',['id'=>1,'status'=>'rejected','finance_notes'=>'Ganti keputusan'],$adminSession,$adminToken)['code']===409,'Reimbursement cannot silently overwrite decided claim');check(ac_one($db,"SELECT COUNT(*) AS n FROM accounting_audit_logs WHERE entity_type='reimbursement' AND entity_id='1'")['n']==1,'Reimbursement decision has one actor audit event');
        check($send('accounting.php','POST',['action'=>'permission','role'=>'admin','permission'=>'approve','allowed'=>true],$adminSession,$adminToken)['code']===403,'HTTP Admin cannot modify approval policy via direct API');
        $headers=implode(' ',$csv['headers']);check(str_contains($headers,'no-store'),'HTTP financial export is not cached');check($send('finance.php','DELETE',null,$cookie,$csrf)['code']===409,'Legacy financial hard delete disabled');
    }finally{proc_terminate($server);proc_close($server);putenv('CREATIVA_RAB_TEST_DB');if(is_file($log))unlink($log);$dir=sys_get_temp_dir().'/'.$testName.'_proofs';foreach(glob($dir.'/*.bin')?:[]as $p)if(preg_match('/^[a-f0-9]{32}\.bin$/D',basename($p)))unlink($p);if(is_dir($dir))rmdir($dir);}
}
